// coupled-subsystem simulation sketch for: Failure Cascade Universe
const subs = [
  {name:'power', x:0.628, k:0.131},
  {name:'thermal', x:0.569, k:0.117},
  {name:'structural', x:0.486, k:0.067},
  {name:'control', x:0.375, k:0.079},
];
for (let t = 0; t < 60; t++) {
  for (const s of subs) { s.x += s.k * (1 - s.x) - 0.015 * s.x; }
}
const fin = subs.map(s => +s.x.toFixed(4));
console.log(JSON.stringify({subsystems: subs.length, steps: 60,
  finalState: fin, converged: fin.every(v => v > 0 && v < 1.5),
  topic: 'Failure Cascade Universe'}));

